283	    private Location findFood()
284	    {
285	        // Get adjacent locations:
286	        Field field;
287	        field = getField();
288	        List<Location> adjacentLocations = field.adjacentLocations(getLocation());
289	        
290	        Iterator<Location> it = adjacentLocations.iterator();
291	        
292	        while (it.hasNext())
