309	                            {   
310	                                
311	                                return eat(actor);
312	                            }
313	                        }
314	                        else
315	                        {
316	                            
317	                            return eat(actor);
318	                        }
319	                    }
320	                }
321	            }
322	            if(Carcass.class.isInstance(object))
323	            {   
324	                if(canEatCarcass)
325	                {
326	                    Carcass carcass = (Carcass) object;
327	                    if(carcass.isDiseased())
328	                    {
329	                        this.disease = giveDisease();
330	                    }
331	                    sustenanceLevel += carcass.getConsumptionWorth();
332	                    carcass.setDead();
333	                    return where;
334	                }
335	            }
336	        }
337	        
338	        return null;
339	    }
