345	     * Makes the animal eat the food and generate a carcass if necessary.
346	     * @param actor The actor who is to be eaten.
347	     */
348	    private Location eat(Actor actor)
349	    {   
350	        Location location = actor.getLocation();
351	        int actorConsumptionWorth = actor.getConsumptionWorth();
352	        if(actor.becomeCarcass())
353	        {   
354	            actor.setDead();
355	            if((sustenanceLevel + actorConsumptionWorth) > maxSustenanceLevel)
356	            {   
357	                int foodLeft = (sustenanceLevel + consumptionWorth) - maxSustenanceLevel;
358	                sustenanceLevel = this.maxSustenanceLevel;
359	                Carcass carcass = new Carcass(getField(),location,foodLeft);
360	                newCarcass = carcass;
361	                ifCarcass = true;
362	                return getLocation();
363	            }  
364	        }
365	        if(sustenanceLevel + actorConsumptionWorth <= maxSustenanceLevel)
366	        {
367	            sustenanceLevel += actorConsumptionWorth;
368	            return location;
369	        }
370	        return null;
371	    }
372	}

